from collections import defaultdict

class TrieNode:
    def __init__(self):
        self.children = {}
        self.is_end_member = False

def build_trie(words: List[str], indices: List[int]) -> TrieNode:
    root = TrieNode()
    for word, idx in indices:
        node = root
        for char in word:
            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.is_end_member = True
    return root

