def solution(input_str):
    lines = input_str.strip().split('\n')
    n = int(lines[0])

    spaceships = []
    bases = []

    for i in range(n):
        parts = list(map(int, lines[1 + i].split()))
        spaceships.append((parts[0], parts[1], i + 1))

    for i in range(n):
        parts = list(map(int, lines[1 + n + i].split()))
        bases.append((parts[0], parts[1], i + 1))

    cx = sum([s[0] for s in spaceships] + [b[0] for b in bases]) / (2 * n)
    cy = sum([s[1] for s in spaceships] + [b[1] for b in bases]) / (2 * n)

    def angle(p):
        return math.atan2(p[1] - cy, p[0] - cx)

    spaceships.sort(key=angle)
    bases.sort(key=angle)

    result = [bases[i][2] for i in range(n)]

    return '\n'.join(map(str, result))

