import math

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    operations = []
    for i in range(1, n + 1):
        t, x_prime, y = map(int, lines[i].split())
        x = x_prime / 100000.0
        operations.append((t, x, y))

    ans = [-1] * (m + 1)
    reachable = {0}

    for time_step, (op_type, x, y) in enumerate(operations, 1):
        # Make a list of current reachable states (don't modify during iteration)
        current_reachable = list(reachable)
        # Start with current reachable states (we carry them forward)
        new_reachable_set = set(reachable)

        if op_type == 1:  # k := ceil(k + x) repeated up to y times
            for k in current_reachable:
                cur = k
                for _ in range(y):
                    cur = math.ceil(cur + x)
                    if cur > m:
                        break
                    new_reachable_set.add(cur)
        else:  # k := ceil(k * x) repeated up to y times
            for k in current_reachable:
                cur = k
                for _ in range(y):
                    cur = math.ceil(cur * x)
                    if cur > m:
                        break
                    new_reachable_set.add(cur)

        reachable = new_reachable_set

        # Record the earliest time-step for each banana count
        for j in range(1, m + 1):
            if j in reachable and ans[j] == -1:
                ans[j] = time_step

    return ' '.join(map(str, ans[1:])) + '\n'

