def solution(input_str):
    lines = input_str.strip().split('\n')
    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    @lru_cache(maxsize=None)
    def grundy(a_val):
        # Option 1: Remove one cow
        moves = {grundy(a_val - 1)}

        # Option 2: If even, split into k piles
        if a_val > 0 and a_val % 2 == 0:
            x = a_val // 2
            # k piles of size x each
            if k % 2 == 0:
                moves.add(0)
            else:
                moves.add(grundy(x))

        # Find mex
        mex = 0
        while mex in moves:
            mex += 1
        return mex

    xor_sum = 0
    for pile in a:
        xor_sum ^= grundy(pile)

    return "Kevin\n" if xor_sum != 0 else "Nicky\n"

