def solution(input_str):
    lines = input_str.strip().split('\n')
    if not lines:
        return '0'

    n, m = map(int, lines[0].split())

    segment_visits = []
    current_segment = set()

    # Parse events starting from line 1 (after n, m)
    for line in lines[1:]:
        if not line.strip():
            continue
        parts = line.split()
        if parts[0] == '1':
            if current_segment:
                segment_visits.append(current_segment)
                current_segment = set()
        elif parts[0] == '2':
            friend_name = parts[1]
            current_segment.add(friend_name)

    if current_segment:
        segment_visits.append(current_segment)

    # If no segments found
    if not segment_visits:
        return '0'

    # Collect all unique friend names
    all_friends = sorted(set(friend for seg in segment_visits for friend in seg))
    friend_to_idx = {friend: i for i, friend in enumerate(all_friends)}
    num_friends = len(all_friends)

    if num_friends == 0:
        return '0'

    # Build conflict matrix
    conflict = [[False] * num_friends for _ in range(num_friends)]
    for seg in segment_visits:
        friends_in_seg = sorted([friend_to_idx[f] for f in seg if f in friend_to_idx])
        for i in range(len(friends_in_seg)):
            for j in range(i + 1, len(friends_in_seg)):
                conflict[friends_in_seg[i]][friends_in_seg[j]] = True
                conflict[friends_in_seg[j]][friends_in_seg[i]] = True

    # Convert to adjacency bitmask for efficiency
    adj = [0] * num_friends
    for i in range(num_friends):
        mask = 0
        for j in range(num_friends):
            if conflict[i][j]:
                mask |= (1 << j)
        adj[i] = mask

    max_found = [0]

    def solve(idx, selected_mask, count):
        # Update maximum
        if count > max_found[0]:
            max_found[0] = count

        # Pruning: if we can't improve, return
        if count + (num_friends - idx) <= max_found[0]:
            return

        # Base case: processed all friends
        if idx >= num_friends:
            return

        # Branch 1: Try including friend i (if no conflict)
        if not ((1 << idx) & selected_mask):
            i = idx
            # Check if this friend conflicts with any already selected
            can_include = (adj[i] & selected_mask) == 0
            if can_include:
                solve(idx + 1, selected_mask | (1 << idx), count + 1)

        # Branch 2: Don't include this friend
        solve(idx + 1, selected_mask, count)

    solve(0, 0, 0)

    return str(max_found[0])

def solution(input_string):
    lines = input_string.strip().split('\n')
    n, m, q = map(int, lines[0].split())
    e = list(map(int, lines[1].split()))

    queries = []
    for i in range(q):
        parts = list(map(int, lines[2 + i].split()))
        l, r, k = parts
        queries.append((l, r, k))

    MOD = 998244353

    MAX_VAL = max(200005, n + 1)
    factorials = [1] * MAX_VAL
    inv_factorials = [1] * MAX_VAL

    for i in range(1, MAX_VAL):
        factorials[i] = (factorials[i-1] * i) % MOD

    inv_factorials[MAX_VAL - 1] = pow(factorials[MAX_VAL - 1], MOD - 2, MOD)
    for i in range(MAX_VAL - 2, -1, -1):
        inv_factorials[i] = (inv_factorials[i+1] * (i + 1)) % MOD

    prefix_counts = [[0] * n for _ in range(m + 1)]

    for ending in range(1, m + 1):
        for i in range(n):
            prefix_counts[ending][i + 1] = prefix_counts[ending][i]

    for ending in range(1, m + 1):
        for i in range(n):
            if e[i] == ending:
                prefix_counts[ending][i + 1] += 1

    def get_count(ending, l, r):
        return prefix_counts[ending][r] - prefix_counts[ending][l - 1]

    results = []

    for l, r, k in queries:
        actual_endings_used = set()

        total_in_segment = r - l + 1

        ans = 1

        for ending in range(1, m + 1):
            c = get_count(ending, l, r)
            if c > 0:
                actual_endings_used.add(ending)
                if k < c:
                    ans = 0
                    break
                term = 1
                for i in range(c):
                    term = (term * (k - i)) % MOD
                ans = (ans * term) % MOD

        if ans == 0:
            results.append("0")
            continue

        remaining_positions = n - total_in_segment
        ans = (ans * factorials[remaining_positions]) % MOD

        results.append(str(ans))

    return '\n'.join(results)

