import pytest
from collections import defaultdict

def solution(input_str: str) -> str:
    parts = input_str.strip().split('\n')
    n, m = map(int, parts[0].split())
    S = parts[1]
    T = parts[2]

    def check(start: int) -> bool:
        if m > n:
            return False
        mapping = {}  # char -> char
        pairs_seen = set()  # (u, v) pairs

        for i in range(m):
            s_char = S[start + i]
            t_char = T[i]

            # s_char and t_char must either be same (no pair) or be a pair
            if s_char == t_char:
                continue

            # They form a pair relationship
            pair = tuple(sorted((s_char, t_char)))

            # Check if this pair is already defined
            if pair in pairs_seen:
                continue

            # Check consistency - s_char must map to t_char
            if s_char in mapping:
                if mapping[s_char] != t_char:
                    return False
            else:
                mapping[s_char] = t_char

            # Check consistency - t_char must map to s_char
            if t_char in mapping:
                if mapping[t_char] != s_char:
                    return False
            else:
                mapping[t_char] = s_char

            pairs_seen.add(pair)

        # Additional check: each letter can be in at most one pair
        # This is already enforced by the pair set check
        # Also check no three-way conflict exists
        return True

    result = []
    for start in range(n - m + 1):
        if check(start):
            result.append(start + 1)  # 1-indexed positions

    output_lines = [str(len(result))]
    output_lines.append(' '.join(map(str, result)))
    return '\n'.join(output_lines)
