def solution(input_str):
    # Parse input: maxx, maxy, w
    parts = input_str.strip().split()
    if len(parts) < 3:
        return "-1\n"

    maxx = int(parts[0])
    maxy = int(parts[1])
    w = int(parts[2])

    # Function to reverse a number
    def rev(n):
        return int(str(n)[::-1])

    # Function to count lucky tickets in range
    def count_lucky(x, y):
        count = 0
        for a in range(1, x + 1):
            ra = rev(a)
            for b in range(1, y + 1):
                rb = rev(b)
                if a * b == ra * rb:
                    count += 1
        return count

    # Find minimum x*y that gives at least w lucky tickets
    best_x = None
    best_y = None
    best_prod = float('inf')

    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            cnt = count_lucky(x, y)
            if cnt >= w:
                prod = x * y
                if prod < best_prod:
                    best_prod = prod
                    best_x = x
                    best_y = y

    if best_x is None:
        return "-1\n"
    return f"{best_x} {best_y}\n"

