from itertools import combinations_with_replacement, permutations

def solution(input_str):
    n, m, k = map(int, input_str.strip().split())
    MOD = 1000000007

    def is_good(arr):
        r = len(arr)
        if r <= 1:
            return False
        for i in range(r):
            if abs(arr[i] - arr[(i + 1) % r]) != 1:
                return False
        return True

    def count_good_arrays(arr):
        """Count how many distinct good arrays can be formed from this multiset"""
        if len(arr) <= 1:
            return 0

        seen_perms = set()
        good_count = 0

        # Generate all unique permutations
        for perm in set(permutations(arr)):
            if is_good(perm):
                good_count += 1

        return good_count

    ans = 0

    # Generate all non-decreasing arrays
    for r in range(1, n + 1):
        for combo in combinations_with_replacement(range(1, m + 1), r):
            # Count how many good arrays can be formed from this multiset
            good_count = count_good_arrays(combo)
            if 1 <= good_count <= k:
                ans = (ans + 1) % MOD

    return str(ans)

