import sys

def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 3:
        return '0'

    s1 = lines[0].strip()
    s2 = lines[1].strip()
    virus = lines[2].strip()

    m = len(s1)
    n = len(s2)
    v_len = len(virus)

    # Edge case: virus is empty or longer than both strings
    if v_len == 0 or v_len > max(m, n):
        result = []
        dp = [[0] * (m + 1) for _ in range(n + 1)]
        for i in range(1, m + 1):
            for j in range(1, n + 1):
                if s1[i-1] == s2[j-1]:
                    dp[i][j] = dp[i-1][j-1] + 1
                else:
                    dp[i][j] = max(dp[i-1][j], dp[i][j-1])

        i, j = m, n
        while i > 0 and j > 0:
            if s1[i-1] == s2[j-1]:
                result.append(s1[i-1])
                i -= 1
                j -= 1
            elif dp[i-1][j] >= dp[i][j-1]:
                i -= 1
            else:
                j -= 1

        return ''.join(reversed(result)) if result else '0'

    # KMP pi table for virus pattern
    def get_pi(virus):
        pi = [0] * v_len
        k = 0
        for i in range(1, v_len):
            while k > 0 and virus[k] != virus[i]:
                k = pi[k-1]
            if virus[k] == virus[i]:
                k += 1
            pi[i] = k
        return pi

    pi_table = get_pi(virus)

    def get_next_state(k_state, c):
        temp_k = k_state
        while temp_k > 0 and virus[temp_k] != c:
            temp_k = pi_table[temp_k - 1]
        if virus[temp_k] == c:
            temp_k += 1
        return temp_k

    # dp[i][j][state] = max length of LCS when s1[:i] and s2[:j] produce virus state 'state'
    # path[i][j][state] = how we got here: ('match', char) or 'skip1' or 'skip2'
    INF = float('-inf')
    dp = [[[INF] * (v_len + 1) for _ in range(n + 1)] for _ in range(m + 1)]
    path = [[[None] * (v_len + 1) for _ in range(n + 1)] for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            dp[i][j][0] = 0

    for i in range(1, m + 1):
        for j in range(1, n + 1):
            for k in range(v_len + 1):
                # Option 1: skip s1[i-1]
                if dp[i-1][j][k] > dp[i][j][k] or dp[i][j][k] == INF:
                    dp[i][j][k] = max(dp[i][j][k], dp[i-1][j][k])
                    path[i][j][k] = 'skip1'

                # Option 2: skip s2[j-1]
                if dp[i][j-1][k] > dp[i][j][k] or dp[i][j][k] == INF:
                    dp[i][j][k] = max(dp[i][j][k], dp[i][j-1][k])
                    path[i][j][k] = 'skip2'

                # Option 3: match s1[i-1] with s2[j-1]
                if s1[i-1] == s2[j-1]:
                    next_state = get_next_state(k, s1[i-1])
                    if next_state < v_len:  # Don't complete virus
                        if dp[i-1][j-1][k] > INF:
                            new_len = dp[i-1][j-1][k] + 1
                            if new_len > dp[i][j][next_state] or path[i][j][next_state] is None:
                                dp[i][j][next_state] = new_len
                                path[i][j][next_state] = ('match', s1[i-1])

    # Find maximum valid result
    max_len = 0
    best_end_state = 0
    for k in range(v_len + 1):
        if dp[m][n][k] > max_len and dp[m][n][k] > INF:
            max_len = dp[m][n][k]
            best_end_state = k

    if max_len == 0:
        return '0'

    # Reconstruct the solution
    res = []
    i, j = m, n
    k = best_end_state
    cnt = 0

    while i > 0 and j > 0 and cnt < max_len:
        if dp[i][j][k] == INF:
            i -= 1
            j -= 1
            continue

        move = path[i][j][k]
        if move == ('match', c):
            res.append(c)
            cnt += 1
            i -= 1
            j -= 1
        elif move == 'skip1':
            i -= 1
        else:  # skip2
            j -= 1

    return ''.join(reversed(res)) if res else '0'


