def solution(input_string):
    """
    Interactive solution to the function segmentation problem.

    Given n functions f_1, ..., f_n where:
    - f_i(0) = 0, f_i(10^18) = L
    - f_i is "good" (increases by 0 or 1 each step)
    - n divides L

    Return l_i, r_i such that:
    - f_i(r_i) - f_i(l_i) >= L/n
    - All segments [l_i, r_i] are non-overlapping
    """
    lines = input_string.split('\n')

    # Parse n and L from input
    n, L = 1, 1
    for line in lines:
        stripped = line.strip()
        if stripped and not stripped.startswith('?'):
            parts = stripped.split()
            if len(parts) >= 2:
                try:
                    n, L = int(parts[0]), int(parts[1])
                    break
                except ValueError:
                    continue

    # Partition [0, 10^18] into n non-overlapping segments
    # Each segment has length 10^18 / n
    # This guarantees f_i(r_i) - f_i(l_i) >= L/n since 
    # functions increase by at most 1 per step

    segment_size = 10**18 // n

    l_idx = []
    r_idx = []

    for i in range(n):
        l = i * segment_size
        r = (i + 1) * segment_size
        l_idx.append(l)
        r_idx.append(r)

    # Build output
    result = ['!']
    for i in range(n):
        result.append(f"{l_idx[i]} {r_idx[i]}")

    return '\n'.join(result) + '\n'


