        # Position i needs to be covered
        # Either i covers i-1 (i goes L), or someone covers i

        if covered[i]:
            # Already covered, just decide direction for next
            if i + 1 < n:
                # Try to cover next position from left
                if p[i] >= 1:
                    directions[i] = 'R'
                    i += 1
                else:
                    directions[i] = 'L'
                    i += 1
            else:
                directions[i] = 'L'
