        if i + 1 >= n:
            # Last position, cannot be covered from right
            directions[i] = 'L'
            covered[i] = True
            i += 1
            continue

        # Can (i-1) cover i?
        from_left_i = False
        if i > 0:
            l_idx = i - 1
            if p[l_idx] >= i - l_idx:  # = 1
                from_left_i = True
                directions[l_idx] = 'R'
                covered[i] = True

        # Can (i+1) cover i?
