    len_val = len(val_str)
    times = times % MOD  # times might be large

    # We need val repeated times times, where each val has len_val digits
    # Result is val * 10^(len_val*(times-1)) + val * 10^(len_val*(times-2)) + ... + val
    # This is val * (10^(len_val*times) - 1) / (10^(len_val) - 1)
