class RangeConcatCompat:
    """Helper for range concatenation"""
    MOD = 10**9 + 7

    @staticmethod
    def concat_mod(a, b):
        len_b = len(str(b))
        return (a * pow(10, len_b, RangeConcatCompat.MOD)) % RangeConcatCompat.MOD + b % RangeConcatCompat.MOD

    @staticmethod
    def range_concat_mod(start, end):
        if start > end:
            return 0
        if start == end:
            return start % RangeConcatCompat.MOD

        result = start % RangeConcatCompat.MOD
        for val in range(start + 1, end + 1):
            result = RangeConcatCompat.concat_mod(result, val)
        return result

    @staticmethod
    def repeat_expr_mod(val, times):
        if times == 0:
            return 0
        if times == 1:
            return val % RangeConcatCompat.MOD

        val_str = str(val)
        len_val = len(val_str)

        divisor = pow(10, len_val, RangeConcatCompat.MOD) - 1
        if divisor == 0:
            return (val * times) % RangeConcatCompat.MOD

        numerator = pow(10, len_val * times, RangeConcatCompat.MOD) - 1
        denominator_inv = pow(divisor, RangeConcatCompat.MOD - 2, RangeConcatCompat.MOD)

        return (val * numerator * denominator_inv) % RangeConcatCompat.MOD

