# If you want to see how many possible correct binary codes exist (brute-force):
import sys

def solution_bruteforce(input_str):
    """Correct solution counting valid binary codes"""
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        si, ci = lines[i].split()
        attempts.append((si, int(ci)))

    count = 0
    for code in range(1 << n):
        valid = True
        mask = 1
        for attempt_si, attempt_ci in attempts:
            matches = 0
            for pos in range(n):
                trial_bit = (code >> pos) & 1
                attempt_bit = int(attempt_si[pos])
                if trial_bit == attempt_bit:
                    matches += 1
            if matches != attempt_ci:
                valid = False
                break
        if valid:
            count += 1

    return str(count)
